/* LAW20 — ChatGPT作。v30を基準に「法則そのもの」を20種類へ展開。極彩色・自己相似・タッチで構造変化。 */
window.Law20=function(canvas,index){
const ctx=canvas.getContext('2d',{alpha:false});let W=0,H=0,D=1,phase=0,seed=Math.random()*1e6,marks=[];
const N=['IFS','FOLD','BROT','JULIA','DRAGON','KOCH','TREE','CARPET','SPIRAL','ORBIT','MIRROR','RIPPLE','CORAL','FLAME','NEST','TENDRIL','BLOOM','LACE','GROWTH','VOID'];
const P=[['#ff1744','#ffea00','#00e676','#00b0ff','#d500f9'],['#00f5ff','#ff2bd6','#ffe600','#76ff03','#ff6b00'],['#ff0055','#00ffcc','#ffe600','#7c4dff','#ff6d00'],['#ff00a8','#00fff0','#ffff00','#5e00ff','#ff5e00'],['#ff3b30','#ffd60a','#32d74b','#64d2ff','#bf5af2'],['#ff4081','#00e5ff','#76ff03','#ffea00','#7c4dff'],['#ff006e','#fbff12','#00f5d4','#00bbf9','#9b5de5'],['#ff003c','#00e5ff','#ffea00','#00c853','#aa00ff'],['#ff00ff','#00ffff','#ffff00','#ff3300','#33ff66'],['#ff6d00','#00e676','#00b0ff','#d500f9','#ffe600']];
function resize(){D=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*D;canvas.height=H*D;ctx.setTransform(D,0,0,D,0,0)}addEventListener('resize',resize);resize();
function rnd(n){const x=Math.sin(n*127.1+seed*311.7)*43758.5453;return x-Math.floor(x)}
function pal(k,t=0){const p=P[(index+Math.floor(seed*.00001))%P.length];return p[((Math.floor(k+t)%p.length)+p.length)%p.length]}
function bg(){ctx.globalAlpha=1;ctx.fillStyle='#03020a';ctx.fillRect(0,0,W,H)}
function line(a,b,c,d,colr,a1=.7,w=1){ctx.globalAlpha=a1;ctx.strokeStyle=colr;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(a,b);ctx.lineTo(c,d);ctx.stroke()}
function dot(x,y,r,c,a=.8){ctx.globalAlpha=a;ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function field(x,y){let q=0,s=Math.min(W,H);for(const m of marks){const dx=x-m.x,dy=y-m.y,d=Math.hypot(dx,dy);q+=Math.exp(-d*d/(s*s*.045))*(1-dx/s*.35+dy/s*.2)}return q}
function touchAngle(x,y){let q=0,s=Math.min(W,H);for(const m of marks)q+=Math.atan2(y-m.y,x-m.x)*Math.exp(-Math.hypot(x-m.x,y-m.y)**2/(s*s*.035));return q}
function triIFS(){bg();const S=Math.min(W,H)*.72,cx=W/2,cy=H/2;let x=0,y=0;for(let i=0;i<36000;i++){const k=Math.floor(rnd(i+1)*3),tx=[0,1,-1][k]*S*.5,ty=[-1,1,1][k]*S*.42;const f=.5+field(cx+x,cy+y)*.025;x+=(tx-x)*f;y+=(ty-y)*f;if(i>30&&i%2===0)dot(cx+x,cy+y,.7,pal(i*.008,phase*2),.78)}}
function fold(){bg();const S=Math.min(W,H)*.9,cx=W/2,cy=H/2;for(let y=-S;y<S;y+=3)for(let x=-S;x<S;x+=3){let a=x/S,b=y/S;for(let d=0;d<8;d++){const r=Math.hypot(a,b),ang=Math.atan2(b,a);a=Math.abs(((ang/Math.PI*4+field(cx+x,cy+y)*.12+phase*.03)%2)-1)*.55*Math.cos(ang)-Math.sin(ang)*r*.7;b=Math.abs(((ang/Math.PI*4+field(cx+x,cy+y)*.12+phase*.03)%2)-1)*.55*Math.sin(ang)+Math.cos(ang)*r*.7}if((a*a+b*b)<.42){ctx.fillStyle=pal((a-b)*9,phase*3);ctx.globalAlpha=.72;ctx.fillRect(cx+x*.75,cy+y*.75,2.5,2.5)}}}
function escapeJulia(julia){bg();const S=Math.min(W,H)*.72,m=marks[0]||{x:W*.65,y:H*.45},cx0=-.74+(m.x/W-.5)*.7,cy0=.12+(m.y/H-.5)*.65;for(let py=0;py<H;py+=3)for(let px=0;px<W;px+=3){let x=(px-W/2)/S*3.1,y=(py-H/2)/S*3.1,cx=julia?cx0:x,cy=julia?cy0:y,zx=julia?x:0,zy=julia?y:0,n=0;for(;n<52;n++){const xx=zx*zx-zy*zy+cx,yy=2*zx*zy+cy;zx=xx;zy=yy;if(zx*zx+zy*zy>16)break}if(n<52){const v=n+.5-Math.log2(Math.log2(Math.max(2,Math.hypot(zx,zy))));ctx.fillStyle=pal(v*.24,phase*2);ctx.globalAlpha=.95;ctx.fillRect(px,py,3,3)}}}
function dragon(){bg();const S=Math.min(W,H)*.72;let turns=[1];for(let r=0;r<13;r++){const rev=turns.slice().reverse().map(v=>-v);turns=turns.concat([1],rev)}let a=-.45+field(W/2,H/2)*.12,x=W/2-S*.32,y=H/2+S*.16,l=S*.0058;for(let i=0;i<turns.length;i++){const nx=x+Math.cos(a)*l,ny=y+Math.sin(a)*l;line(x,y,nx,ny,pal(i*.006,phase*2),.78,1.05);x=nx;y=ny;a+=turns[i]*Math.PI/2*(1+field(x,y)*.015)}}
function koch(){bg();const S=Math.min(W,H)*.72,cx=W/2,cy=H/2;function k(x1,y1,x2,y2,d,n){if(d===0){line(x1,y1,x2,y2,pal(n*.12,phase),.82,1.05);return}const dx=(x2-x1)/3,dy=(y2-y1)/3,a=x1+dx,b=y1+dy,c=x1+dx*2,e=y1+dy*2,ang=Math.PI/3+field((a+c)/2,(b+e)/2)*.25,px=a+dx*Math.cos(ang)-dy*Math.sin(ang),py=b+dx*Math.sin(ang)+dy*Math.cos(ang);k(x1,y1,a,b,d-1,n);k(a,b,px,py,d-1,n+1);k(px,py,c,e,d-1,n+2);k(c,e,x2,y2,d-1,n+3)}for(let j=0;j<3;j++){const a=j*Math.PI*2/3+phase*.04,x1=cx+Math.cos(a)*S*.36,y1=cy+Math.sin(a)*S*.36,x2=cx+Math.cos(a+2.094)*S*.36,y2=cy+Math.sin(a+2.094)*S*.36;k(x1,y1,x2,y2,4,j*20)}}
function tree(){bg();const S=Math.min(W,H);function t(x,y,l,a,d,n){if(d<0||l<2)return;const f=field(x,y),aa=a+Math.sin(n*1.73+d)*.11+f*.22,x2=x+Math.cos(aa)*l,y2=y+Math.sin(aa)*l;line(x,y,x2,y2,pal(n*.18,phase*2),.72,.65+d*.12);const spread=.32+f*.025;t(x2,y2,l*.73,aa-spread,d-1,n+1);t(x2,y2,l*.73,aa+spread,d-1,n+2)}t(W/2,H*.92,S*.25,-Math.PI/2,8,0)}
function carpet(){bg();const S=Math.min(W,H)*.78;function c(x,y,s,d,n){if(d===0){ctx.fillStyle=pal(n*.11,phase*2);ctx.globalAlpha=.86;ctx.fillRect(x-s/2,y-s/2,s,s);return}const g=s/3;for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++)if(Math.abs(xx)+Math.abs(yy)>0){const f=field(x+xx*g,y+yy*g);c(x+xx*g*(1+f*.03),y+yy*g*(1+f*.03),g,d-1,n+xx+yy+4)}}c(W/2,H/2,S,5,0)}
function spiral(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let q=0;q<55;q++){let px=cx,py=cy;for(let i=1;i<180;i++){const u=i/180,r=u*S*.48*(1+q*.008),a=u*Math.PI*(3.5+q*.025)+phase*(q%2?-.12:.12)+touchAngle(px,py)*.03;const x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r*(.55+.45*u);line(px,py,x,y,pal(q*.22+i*.015,phase*2),.32,.7);if(i%7===0)dot(x,y,1.1,pal(q*.22+i*.015,phase*2),.65);px=x;py=y}}}
function orbit(){bg();const S=Math.min(W,H),c=marks[0]||{x:W/2,y:H/2};for(let j=0;j<26;j++){let x=c.x,y=c.y,a=rnd(j)*6.28;for(let i=0;i<260;i++){const r=S*(.006+j*.006+i*.0014),f=field(x,y),na=a+.055+f*.004+Math.sin(i*.03+phase)*.0015,nx=c.x+Math.cos(na)*r,ny=c.y+Math.sin(na)*r*.66;line(x,y,nx,ny,pal(j*.18,phase*2),.26,.65);x=nx;y=ny;a=na}}}
function mirror(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;function m(x,y,s,d,n,a){if(d<0||s<1)return;ctx.globalAlpha=.65;ctx.strokeStyle=pal(n*.18,phase);ctx.lineWidth=.8+d*.12;ctx.strokeRect(x-s/2,y-s/2,s,s);const f=field(x,y),ang=a+f*.5+phase*.02,q=s*.46;for(let k=0;k<4;k++){const aa=ang+k*Math.PI/2,xx=x+Math.cos(aa)*s*.31,yy=y+Math.sin(aa)*s*.31;m(xx,yy,s*.46,d-1,n+k+1,aa)}}m(cx,cy,S*.62,5,0,0)}
function ripple(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let q=0;q<18;q++){let px=cx,py=cy;const R=S*.035+q*S*.027;for(let i=0;i<=260;i++){const a=i/260*6.283,r=R*(1+.22*Math.sin(a*(q%5+3)+phase*.7)+.12*Math.sin(a*11-q)+field(cx+Math.cos(a)*R,cy+Math.sin(a)*R)*.25),x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;if(i)line(px,py,x,y,pal(q*.31,phase*2),.62,q%3===0?1.15:.6);px=x;py=y}}}
function coral(){bg();const S=Math.min(W,H);function c(x,y,l,a,d,n){if(d<0||l<1.2)return;const f=field(x,y),aa=a+Math.sin(n*2.1)*.08+f*.65,x2=x+Math.cos(aa)*l,y2=y+Math.sin(aa)*l;line(x,y,x2,y2,pal(n*.16,phase*2),.7,.6+d*.1);c(x2,y2,l*.69,aa-.43,d-1,n+1);c(x2,y2,l*.69,aa+.43,d-1,n+2);if(d%2===0)c(x2,y2,l*.48,aa+.15,d-2,n+3)}c(W/2,H*.94,S*.19,-Math.PI/2,8,0)}
function flame(){bg();const S=Math.min(W,H),base=marks[0]||{x:W/2,y:H*.9};for(let i=0;i<150;i++){let x=base.x+(rnd(i)-.5)*S*.38,y=base.y,a=-Math.PI/2+(rnd(i+2)-.5)*1.35,l=S*(.045+rnd(i+4)*.2);for(let d=0;d<9;d++){const f=field(x,y),aa=a+Math.sin(i*.7+d+phase)*.06+f*.18,nx=x+Math.cos(aa)*l,ny=y+Math.sin(aa)*l;line(x,y,nx,ny,pal(i*.07+d*.4,phase*2),.5,1.0);x=nx;y=ny;a=aa;l*=.72}}}
function nest(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;function n(x,y,s,d,k){if(d<0||s<2)return;const f=field(x,y);ctx.globalAlpha=.58;ctx.strokeStyle=pal(k*.3,phase);ctx.lineWidth=.8;ctx.beginPath();ctx.arc(x,y,s,0,6.283);ctx.stroke();const q=.48+f*.05;for(let j=0;j<3;j++){const a=j*2.094+phase*.03+f;n(x+Math.cos(a)*s*(1-q),y+Math.sin(a)*s*(1-q),s*q,d-1,k+j+1)}}n(cx,cy,S*.36,6,0)}
function tendril(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let j=0;j<34;j++){let x=cx+(rnd(j)-.5)*S*.06,y=cy+(rnd(j+40)-.5)*S*.06,a=rnd(j+80)*6.28,l=S*.006+j*S*.002;for(let d=0;d<180;d++){const f=field(x,y),aa=a+Math.sin(d*.17+j)*.045+touchAngle(x,y)*.018,nx=x+Math.cos(aa)*l,ny=y+Math.sin(aa)*l;line(x,y,nx,ny,pal(j*.19+d*.025,phase*2),.34,.7);x=nx;y=ny;a=aa;l*=1.004+f*.0008}}}
function bloom(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let r=0;r<13;r++){const R=S*.035+r*S*.027;let px=0,py=0;for(let i=0;i<=360;i++){const a=i/360*6.283,pet=1+.38*Math.pow(Math.sin(a*(r+3)+phase*.5),2)+field(cx+Math.cos(a)*R,cy+Math.sin(a)*R)*.25,rr=R*pet,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;if(i)line(px,py,x,y,pal(r*.4,phase*2),.48,1);px=x;py=y}}}
function lace(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let k=0;k<16;k++){let px=0,py=0;for(let i=0;i<=300;i++){const a=i/300*6.283,rr=S*.035+k*S*.03*(1+.14*Math.sin(a*(k%6+2)+phase)+.09*Math.sin(a*17))+field(cx,cy)*S*.01,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;if(i)line(px,py,x,y,pal(k*.25,phase*2),.42,k%4===0?1.2:.55);px=x;py=y}}}
function growth(){bg();const S=Math.min(W,H);function g(x,y,l,a,d,n){if(d<0||l<1)return;const f=field(x,y),aa=a+f*.8+Math.sin(n+phase)*.015,nx=x+Math.cos(aa)*l,ny=y+Math.sin(aa)*l;line(x,y,nx,ny,pal(n*.21+d*.3,phase*2),.7,.65+d*.1);g(nx,ny,l*.72,aa-.48,d-1,n+1);g(nx,ny,l*.72,aa+.48,d-1,n+2)}for(let j=0;j<5;j++)g(W*(.18+j*.16),H*.95,S*.14,-Math.PI/2+j*.08,8,j*3)}
function voids(){bg();const S=Math.min(W,H);function v(x,y,s,d,n){if(d<0||s<2)return;const f=field(x,y),q=.47+f*.035;ctx.globalAlpha=.8;ctx.strokeStyle=pal(n*.17,phase);ctx.lineWidth=Math.max(.45,d*.16);ctx.strokeRect(x-s/2,y-s/2,s,s);if(d===0)return;for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++)if(xx||yy){const hole=(xx===0&&yy===0)||((xx*yy!==0)&&((n+d)%3===0));if(!hole)v(x+xx*s/3*q,y+yy*s/3*q,s/3*q,d-1,n+xx+yy+4)}}v(W/2,H/2,S*.78,6,0)}
function render(p=phase){phase=p;switch(index){case 0:triIFS();break;case 1:fold();break;case 2:escape(false);break;case 3:escape(true);break;case 4:dragon();break;case 5:koch();break;case 6:tree();break;case 7:carpet();break;case 8:spiral();break;case 9:orbit();break;case 10:mirror();break;case 11:ripple();break;case 12:coral();break;case 13:flame();break;case 14:nest();break;case 15:tendril();break;case 16:bloom();break;case 17:lace();break;case 18:growth();break;case 19:voids();break}ctx.globalAlpha=1}
function mutate(){seed=Math.random()*1e6;marks=[];for(let i=0;i<2;i++)marks.push({x:W*(.2+Math.random()*.6),y:H*(.2+Math.random()*.6)});render(phase)}
function reset(){marks=[];seed=Math.random()*1e6;render(phase)}
function add(x,y){if(window.APKit&&APKit.isUI(x,y))return true;marks.push({x,y});if(marks.length>4)marks.shift();render(phase);return true}
canvas.addEventListener('pointerdown',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;add(e.clientX,e.clientY)});
canvas.addEventListener('pointermove',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;if(e.buttons&&marks.length){marks[marks.length-1]={x:e.clientX,y:e.clientY};render(phase)}});
canvas.addEventListener('pointerup',()=>{});canvas.addEventListener('pointercancel',()=>{});
APKit.init({canvas,gifName:'law-'+String(index+1).padStart(2,'0')+'-'+N[index].toLowerCase()+'-loop',clockFormat:'spec',loopFrame:function(p){render(p)},buttons:[{label:'✦',name:'mutate',onClick:mutate},{label:'↻',name:'reset',onClick:reset}]});render(0);function tick(){phase=(phase+.0062831853)%6.283185307;render(phase);requestAnimationFrame(tick)}tick();
};
